      ICmpInst::isImpliedByMatchingCmp(SignedLPred, RPred) == false)
    return false;
}

// Take SLT as an example:  L0:x < L1:y and C <= 0
//                      ==> R0:(x -nsw y) < R1:(-C) is true

  //                      ==> R0:(x -nsw y) < R1:(-C) is true
